<script setup lang="ts">
import { computed, nextTick, onMounted, reactive, ref, watch } from "vue";
import { api, errorMessage } from "@/api/client";
import type { LocationSummary, SpeciesSummary } from "@/api/types";
import ObservationSpeciesAssistant, { type AssistantTaxon, type SpeciesExtraction } from "@/components/observations/ObservationSpeciesAssistant.vue";

interface Subspecies { id: number; chinese_name: string | null; scientific_name: string }
interface TaxonGenus { id: number; chinese_name: string; scientific_name: string }
interface TaxonFamily extends TaxonGenus { genera: TaxonGenus[] }
interface TaxonOrder extends TaxonGenus { families: TaxonFamily[] }
interface Additional { species: SpeciesSummary; photo_type: "individual" | "group"; sex: string; life_stage: string; subspecies_id: number | null; subspecies: Subspecies[]; notes: string }
type RichLocation = LocationSummary & { country_code?: string; country_name?: string; admin1_code?: string };

const props = defineProps<{ species: SpeciesSummary[]; locations: RichLocation[] }>();
const emit = defineEmits<{ close: []; saved: [observationId: number] }>();
const speciesId = ref(props.species[0]?.id ? String(props.species[0].id) : "new"); const speciesQuery = ref(""); const primarySubspecies = ref<Subspecies[]>([]);
const taxonomy = ref<TaxonOrder[]>([]); const orderId = ref("new"); const familyId = ref("new"); const genusId = ref("new");
const newSpecies = reactive({ order_chinese: "", order_scientific: "", family_chinese: "", family_scientific: "", genus_chinese: "", genus_scientific: "", chinese_name: "", scientific_name: "", iucn_status: "NE", china_status: "", has_subspecies: false, subspecies_list: "" });
const form = reactive({ photo_type: "individual" as "individual" | "group", sex: "unknown", life_stage: "unknown", subspecies_id: null as number | null, observed_at: new Date(Date.now() - new Date().getTimezoneOffset() * 60000).toISOString().slice(0, 16), season: "spring", latitude: null as number | null, longitude: null as number | null, country_code: "CN", country_name: "中国", admin1_code: "", admin1_name: "", locality: "", notes: "", location_id: "" });
const photo = ref<File | null>(null); const audio = ref<File[]>([]); const photoStatus = ref("选择照片后将自动读取 EXIF 拍摄时间。"); const status = ref(""); const additional = ref<Additional[]>([]); const additionalId = ref("");
const filteredSpecies = computed(() => { const q = speciesQuery.value.trim().toLocaleLowerCase(); return props.species.filter((item) => `${item.catalog_number} ${item.chinese_name} ${item.scientific_name} ${item.family_name} ${item.genus_name}`.toLocaleLowerCase().includes(q)); });
const selectedOrder = computed(() => taxonomy.value.find((item) => String(item.id) === orderId.value)); const families = computed(() => selectedOrder.value?.families || []); const selectedFamily = computed(() => families.value.find((item) => String(item.id) === familyId.value)); const genera = computed(() => selectedFamily.value?.genera || []);
const availableAdditional = computed(() => { const used = new Set(additional.value.map((item) => item.species.id)); return props.species.filter((item) => String(item.id) !== speciesId.value && !used.has(item.id)); });
watch(orderId, () => { familyId.value = "new"; genusId.value = "new"; }); watch(familyId, () => { genusId.value = "new"; });
watch(speciesId, async (value) => { form.subspecies_id = null; if (value === "new") { primarySubspecies.value = []; return; } try { primarySubspecies.value = (await api<{ subspecies: Subspecies[] }>(`/api/species/${value}`)).subspecies; } catch (caught) { status.value = errorMessage(caught); } });
function taxon(level: "order" | "family" | "genus"): { chinese_name: string; scientific_name: string } { const selected = level === "order" ? selectedOrder.value : level === "family" ? selectedFamily.value : genera.value.find((item) => String(item.id) === genusId.value); return selected ? { chinese_name: selected.chinese_name, scientific_name: selected.scientific_name } : { chinese_name: newSpecies[`${level}_chinese`], scientific_name: newSpecies[`${level}_scientific`] }; }
function parseSubspecies(): Array<{ scientific_name: string; chinese_name: string | null }> { return newSpecies.subspecies_list.split(/\r?\n/).map((line) => line.trim()).filter(Boolean).map((line) => { const [scientific, chinese] = line.split("|").map((part) => part.trim()); return { scientific_name: scientific, chinese_name: chinese || null }; }); }
function normalized(value: string | null | undefined): string { return String(value || "").normalize("NFKC").toLocaleLowerCase().replace(/[^\p{L}\p{N}]+/gu, ""); }
function taxonMatch<T extends TaxonGenus>(items: T[], suggestion: AssistantTaxon): T | undefined { const keys = [suggestion.chinese_name, suggestion.scientific_name].map(normalized).filter(Boolean); return items.find((item) => keys.some((key) => [item.chinese_name, item.scientific_name].map(normalized).some((value) => value.includes(key) || key.includes(value)))); }
async function applyAssistant(extraction: SpeciesExtraction): Promise<void> { const order = taxonMatch(taxonomy.value, extraction.order); orderId.value = order ? String(order.id) : "new"; if (!order) { newSpecies.order_chinese = extraction.order.chinese_name || ""; newSpecies.order_scientific = extraction.order.scientific_name || ""; } await nextTick(); const family = taxonMatch(families.value, extraction.family); familyId.value = family ? String(family.id) : "new"; if (!family) { newSpecies.family_chinese = extraction.family.chinese_name || ""; newSpecies.family_scientific = extraction.family.scientific_name || ""; } await nextTick(); const genus = taxonMatch(genera.value, extraction.genus); genusId.value = genus ? String(genus.id) : "new"; if (!genus) { newSpecies.genus_chinese = extraction.genus.chinese_name || ""; newSpecies.genus_scientific = extraction.genus.scientific_name || ""; } newSpecies.chinese_name = extraction.species.chinese_name || ""; newSpecies.scientific_name = extraction.species.scientific_name || ""; newSpecies.has_subspecies = extraction.subspecies.length > 0; newSpecies.subspecies_list = extraction.subspecies.map((item) => [item.scientific_name, item.chinese_name].filter(Boolean).join(" | ")).filter(Boolean).join("\n"); }
async function photoChanged(event: Event): Promise<void> { const file = (event.target as HTMLInputElement).files?.[0] || null; photo.value = file; if (!file) return; photoStatus.value = "正在读取 EXIF 拍摄时间…"; const body = new FormData(); body.append("photo", file); try { const result = await api<{ observed_at: string | null }>("/api/media/exif-time", { method: "POST", body }); if (result.observed_at) { form.observed_at = result.observed_at; photoStatus.value = `已从照片读取拍摄时间：${result.observed_at.replace("T", " ")}`; } else photoStatus.value = "照片中没有可用的 EXIF 拍摄时间，请手动填写。"; } catch (caught) { photoStatus.value = errorMessage(caught); } }
function audioChanged(event: Event): void { audio.value = [...((event.target as HTMLInputElement).files || [])]; }
function selectLocation(): void { const location = props.locations.find((item) => String(item.id) === form.location_id); if (!location) return; form.latitude = location.center_latitude; form.longitude = location.center_longitude; form.country_code = location.country_code || "CN"; form.country_name = location.country_name || "中国"; form.admin1_code = location.admin1_code || ""; form.admin1_name = location.admin1_name; form.locality = location.name; }
function useLocation(): void { navigator.geolocation.getCurrentPosition(({ coords }) => { form.latitude = coords.latitude; form.longitude = coords.longitude; }, () => { status.value = "无法读取设备位置，请手动填写经纬度"; }); }
async function addAdditional(): Promise<void> { const item = props.species.find((value) => String(value.id) === additionalId.value); if (!item || additional.value.length >= 9) return; try { const detail = await api<{ subspecies: Subspecies[] }>(`/api/species/${item.id}`); additional.value.push({ species: item, photo_type: "individual", sex: "unknown", life_stage: "unknown", subspecies_id: null, subspecies: detail.subspecies, notes: "" }); additionalId.value = ""; } catch (caught) { status.value = errorMessage(caught); } }
async function submit(): Promise<void> { if (!photo.value) { status.value = "请选择 JPEG/JPG 照片。"; return; } status.value = "正在校验并保存…"; const isNew = speciesId.value === "new"; const individual = form.photo_type === "individual"; const payload = { species_id: isNew ? null : Number(speciesId.value), location_id: form.location_id ? Number(form.location_id) : null, new_species: isNew ? { order: taxon("order"), family: taxon("family"), genus: taxon("genus"), chinese_name: newSpecies.chinese_name, scientific_name: newSpecies.scientific_name, iucn_status: newSpecies.iucn_status, china_protection_status: newSpecies.china_status || null, has_subspecies: newSpecies.has_subspecies, subspecies: newSpecies.has_subspecies ? parseSubspecies() : [], notes: null } : null, subspecies_id: !isNew && individual ? form.subspecies_id : null, subspecies_scientific_name: null, photo_type: form.photo_type, observed_at: form.observed_at, latitude: form.latitude, longitude: form.longitude, country_code: form.country_code, country_name: form.country_name, admin1_code: form.admin1_code, admin1_name: form.admin1_name, locality: form.locality, season: form.season, season_note: null, sex: individual ? form.sex : null, life_stage: individual ? form.life_stage : null, notes: form.notes || null, additional_species: additional.value.map((item) => ({ species_id: item.species.id, photo_type: item.photo_type, sex: item.photo_type === "individual" ? item.sex : null, life_stage: item.photo_type === "individual" ? item.life_stage : null, subspecies_id: item.photo_type === "individual" ? item.subspecies_id : null, notes: item.notes || null })) }; const body = new FormData(); body.append("payload", JSON.stringify(payload)); body.append("photo", photo.value); audio.value.forEach((file) => body.append("audio", file)); try { const result = await api<{ observation_id: number }>("/api/observations", { method: "POST", body }); emit("saved", result.observation_id); } catch (caught) { status.value = errorMessage(caught); } }
onMounted(async () => { try { taxonomy.value = await api<TaxonOrder[]>("/api/taxonomy/tree"); if (speciesId.value !== "new") primarySubspecies.value = (await api<{ subspecies: Subspecies[] }>(`/api/species/${speciesId.value}`)).subspecies; } catch (caught) { status.value = errorMessage(caught); } });
</script>

<template>
  <form @submit.prevent="submit"><header class="dialog-header"><div><p class="eyebrow">NEW OBSERVATION</p><h2>登记新的田野记录</h2></div><button type="button" class="icon-button" @click="$emit('close')">×</button></header><div class="form-scroll">
    <ObservationSpeciesAssistant v-if="speciesId === 'new'" @apply="applyAssistant" />
    <fieldset><legend><span>01</span> 目标物种</legend><div class="form-grid"><label class="full-field">搜索已有图鉴物种<input v-model="speciesQuery" type="search" placeholder="中文名、拉丁学名、科名或属名" /></label><label class="full-field">选择图鉴物种<select v-model="speciesId"><option value="new">＋ 登记新物种</option><option v-for="item in filteredSpecies" :key="item.id" :value="String(item.id)">{{ item.catalog_number }} · {{ item.chinese_name }} · {{ item.scientific_name }}</option></select></label><template v-if="speciesId === 'new'"><label>目<select v-model="orderId"><option value="new">新增目</option><option v-for="item in taxonomy" :key="item.id" :value="String(item.id)">{{ item.chinese_name }} · {{ item.scientific_name }}</option></select></label><label v-if="orderId === 'new'">目中文名<input v-model="newSpecies.order_chinese" required /></label><label v-if="orderId === 'new'">目拉丁学名<input v-model="newSpecies.order_scientific" required /></label><label>科<select v-model="familyId"><option value="new">新增科</option><option v-for="item in families" :key="item.id" :value="String(item.id)">{{ item.chinese_name }} · {{ item.scientific_name }}</option></select></label><label v-if="familyId === 'new'">科中文名<input v-model="newSpecies.family_chinese" required /></label><label v-if="familyId === 'new'">科拉丁学名<input v-model="newSpecies.family_scientific" required /></label><label>属<select v-model="genusId"><option value="new">新增属</option><option v-for="item in genera" :key="item.id" :value="String(item.id)">{{ item.chinese_name }} · {{ item.scientific_name }}</option></select></label><label v-if="genusId === 'new'">属中文名<input v-model="newSpecies.genus_chinese" required /></label><label v-if="genusId === 'new'">属拉丁学名<input v-model="newSpecies.genus_scientific" required /></label><label>种中文名<input v-model="newSpecies.chinese_name" required /></label><label>种拉丁学名<input v-model="newSpecies.scientific_name" required /></label><label>IUCN 等级<select v-model="newSpecies.iucn_status"><option v-for="item in ['NE','LC','NT','VU','EN','CR','EW','EX']" :key="item">{{ item }}</option></select></label><label>中国保护等级<select v-model="newSpecies.china_status"><option value="">无</option><option value="three_protected">三有</option><option value="level_2">二级</option><option value="level_1">一级</option></select></label><label class="check-field full-field"><input v-model="newSpecies.has_subspecies" type="checkbox" /><span>该物种存在亚种</span></label><label v-if="newSpecies.has_subspecies" class="full-field">完整亚种名单<textarea v-model="newSpecies.subspecies_list" rows="3" required placeholder="每行一个：拉丁学名 | 可选中文名"></textarea></label></template></div></fieldset>
    <fieldset><legend><span>02</span> 照片与个体</legend><div class="form-grid"><label class="full-field file-field">JPEG/JPG 照片（不超过 10 MB）<input type="file" accept="image/jpeg,.jpg,.jpeg" required @change="photoChanged" /><span class="field-hint">{{ photoStatus }}</span></label><label>照片类型<select v-model="form.photo_type"><option value="individual">个体照片</option><option value="group">群体照片</option></select></label><template v-if="form.photo_type === 'individual'"><label>性别<select v-model="form.sex"><option value="unknown">未知</option><option value="male">雄性</option><option value="female">雌性</option></select></label><label>生命阶段<select v-model="form.life_stage"><option value="unknown">未知</option><option value="egg">卵</option><option value="chick">雏鸟</option><option value="subadult">亚成</option><option value="adult">成鸟</option></select></label><label v-if="speciesId !== 'new'">亚种<select v-model="form.subspecies_id"><option :value="null">未知 / 无亚种</option><option v-for="item in primarySubspecies" :key="item.id" :value="item.id">{{ item.chinese_name || item.scientific_name }}</option></select></label></template><label class="full-field file-field">MP3 录音（可多选）<input type="file" accept="audio/mpeg,.mp3" multiple @change="audioChanged" /></label></div></fieldset>
    <fieldset><legend><span>03</span> 照片中的其他物种</legend><div class="form-grid"><label class="full-field">选择已有图鉴物种<select v-model="additionalId"><option value="">选择物种</option><option v-for="item in availableAdditional" :key="item.id" :value="String(item.id)">{{ item.chinese_name }} · {{ item.scientific_name }}</option></select></label><button class="secondary-button full-field" type="button" @click="addAdditional">＋ 添加到这笔观察</button><article v-for="(item, index) in additional" :key="item.species.id" class="additional-species-entry full-field"><header><span><strong>{{ item.species.chinese_name }}</strong><small>{{ item.species.scientific_name }}</small></span><button type="button" @click="additional.splice(index, 1)">移除</button></header><div class="form-grid"><label>照片类型<select v-model="item.photo_type"><option value="individual">个体照片</option><option value="group">群体照片</option></select></label><template v-if="item.photo_type === 'individual'"><label>性别<select v-model="item.sex"><option value="unknown">未知</option><option value="male">雄性</option><option value="female">雌性</option></select></label><label>生命阶段<select v-model="item.life_stage"><option value="unknown">未知</option><option value="egg">卵</option><option value="chick">雏鸟</option><option value="subadult">亚成</option><option value="adult">成鸟</option></select></label><label>亚种<select v-model="item.subspecies_id"><option :value="null">未知 / 无亚种</option><option v-for="sub in item.subspecies" :key="sub.id" :value="sub.id">{{ sub.chinese_name || sub.scientific_name }}</option></select></label></template><label class="full-field">该物种备注<textarea v-model="item.notes" rows="2"></textarea></label></div></article></div></fieldset>
    <fieldset><legend><span>04</span> 时间、地点与环境</legend><div class="form-grid"><label class="full-field">地点资料库<select v-model="form.location_id" @change="selectLocation"><option value="">暂不关联地点</option><option v-for="item in locations" :key="item.id" :value="String(item.id)">{{ item.name }} · {{ item.admin1_name }}</option></select></label><label>拍摄时间<input v-model="form.observed_at" type="datetime-local" step="60" required /></label><label>季节<select v-model="form.season"><option value="spring">春</option><option value="summer">夏</option><option value="autumn">秋</option><option value="winter">冬</option><option value="other">其他</option></select></label><label>纬度<input v-model.number="form.latitude" type="number" min="-90" max="90" step="any" required /></label><label>经度<input v-model.number="form.longitude" type="number" min="-180" max="180" step="any" required /></label><button type="button" class="secondary-button full-field" @click="useLocation">使用当前设备位置</button><label>国家代码<input v-model="form.country_code" required /></label><label>国家名称<input v-model="form.country_name" required /></label><label>一级行政区代码<input v-model="form.admin1_code" required /></label><label>一级行政区名称<input v-model="form.admin1_name" required /></label><label class="full-field">具体地点<input v-model="form.locality" required /></label><label class="full-field">备注<textarea v-model="form.notes" rows="3"></textarea></label></div></fieldset>
  </div><footer class="dialog-footer"><span role="status">{{ status }}</span><button type="submit" class="primary-button">保存并入藏</button></footer></form>
</template>
